-- Reference schema : generated by Hibernate (hibernate.hbm2ddl.auto=update)
-- and kept here to make the correspondence with devplatform.xsd explicit.
--
--   DevPlatform/@organisation              -> plateforme.organisation
--   DevPlatform/Projets/Projet/@id         -> projets.id
--   Projet/@lang                           -> projets.lang
--   Projet/Nom                             -> projets.nom
--   Projet/Statut                          -> projets.statut
--   Projet/Equipe/Developpeur/@id,@role    -> developpeurs.id, developpeurs.role
--   Developpeur/Nom, Email                 -> developpeurs.nom, developpeurs.email
--   Projet/Taches/Tache/@id,@priorite,@type-> taches.id, taches.priorite, taches.type
--   Tache/Titre, TempsEstime, Etat         -> taches.titre, taches.temps_estime, taches.etat

CREATE TABLE IF NOT EXISTS plateforme (
    code         VARCHAR(32) PRIMARY KEY,
    organisation VARCHAR(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS projets (
    id      VARCHAR(64) PRIMARY KEY,
    nom     VARCHAR(255) NOT NULL,
    statut  VARCHAR(64)  NOT NULL,
    lang    VARCHAR(32)  NOT NULL
);

CREATE TABLE IF NOT EXISTS developpeurs (
    id         VARCHAR(64) PRIMARY KEY,
    nom        VARCHAR(255) NOT NULL,
    email      VARCHAR(255) NOT NULL,
    role       VARCHAR(64)  NOT NULL,
    projet_id  VARCHAR(64)  NOT NULL REFERENCES projets(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS taches (
    id            VARCHAR(64) PRIMARY KEY,
    titre         VARCHAR(255) NOT NULL,
    temps_estime  INTEGER      NOT NULL,
    etat          VARCHAR(64)  NOT NULL,
    priorite      VARCHAR(64)  NOT NULL,
    type          VARCHAR(64)  NOT NULL,
    projet_id     VARCHAR(64)  NOT NULL REFERENCES projets(id) ON DELETE CASCADE
);

INSERT INTO plateforme (code, organisation)
VALUES ('DEFAULT', 'DevPlatform')
ON CONFLICT (code) DO NOTHING;
